// ============================================
// MARKS MODULE - U1/U2/U3 SYSTEM (OPTIMIZED)
// U1, U2, U3 each out of 20 with validation
// TEACHERS: Can ADD marks but CANNOT EDIT marks
// GRADE COLORS: From olevel_grades table
// ALL BUTTONS REMAIN VISIBLE
// FAST FILTERS & PROPER DELETE
// ============================================

// ============================================
// GLOBAL VARIABLES
// ============================================

let allMarksList = [];
let allStudentsList = [];
let gradingRules = { olevel: [], alevel: { principal: [], subsidiary: [] } };

// Dynamic subjects from database
let dbOlevelSubjects = [];
let dbAlevelPrincipalSubjects = [];
let dbAlevelSubsidiarySubjects = [];

// Batch state
let batchState = {
    class: '',
    stream: '',
    subject: '',
    exam: 'Term 1',
    year: new Date().getFullYear().toString(),
    students: [],
    subjects: [],
    marksMap: {}
};

// Constants
const STREAM_OPTIONS = {
    olevel: ['A', 'B', 'C', 'D'],
    alevel: ['Arts', 'Sciences', 'Business']
};

const EXAM_OPTIONS = ['Term 1', 'Term 2', 'Term 3', 'Mid-Term', 'Mock'];

// ============================================
// HELPER FUNCTIONS
// ============================================

function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function getCurrentYear() {
    return new Date().getFullYear().toString();
}

function getValue(input) {
    if (!input) return 0;
    if (input.value === '' || input.value === null || input.value === undefined) {
        return 0;
    }
    return parseFloat(input.value) || 0;
}

// ============================================
// DEBOUNCE FUNCTION - For fast filtering
// ============================================

function debounce(func, wait) {
    let timeout;
    return function(...args) {
        clearTimeout(timeout);
        timeout = setTimeout(() => func.apply(this, args), wait);
    };
}

// Create debounced filter
const debouncedFilterMarks = debounce(function() {
    applyMarksFilters();
}, 300);

// ============================================
// VALIDATION FUNCTION
// ============================================

function validateUnitInput(input, maxValue) {
    let value = parseFloat(input.value);
    
    if (value > maxValue) {
        input.value = maxValue;
        input.style.backgroundColor = '#f8d7da';
        setTimeout(() => {
            input.style.backgroundColor = '';
        }, 800);
        
        if (!input.dataset.notified) {
            input.dataset.notified = 'true';
            Swal.fire({
                icon: 'warning',
                title: 'Invalid Value',
                text: `Maximum value is ${maxValue}`,
                timer: 1500,
                showConfirmButton: false
            });
            setTimeout(() => {
                input.dataset.notified = '';
            }, 2000);
        }
    }
    
    if (value < 0) {
        input.value = 0;
    }
}

// ============================================
// APPLY FILTERS - FAST & RELIABLE
// ============================================

function applyMarksFilters() {
    const studentFilter = document.getElementById('filterStudent')?.value?.toLowerCase() || '';
    const subjectFilter = document.getElementById('filterSubject')?.value?.toLowerCase() || '';
    const classFilter = document.getElementById('filterClass')?.value || '';
    const streamFilter = document.getElementById('filterStream')?.value || '';
    const yearFilter = document.getElementById('filterYear')?.value || '';
    
    const rows = document.querySelectorAll('#marksTableBody tr');
    let visibleCount = 0;
    const total = rows.length;
    
    rows.forEach(row => {
        if (row.cells && row.cells.length > 1 && !row.innerHTML.includes('No marks found')) {
            let show = true;
            
            if (studentFilter) {
                const student = row.dataset.student || '';
                if (!student.includes(studentFilter)) show = false;
            }
            if (subjectFilter) {
                const subject = row.dataset.subject || '';
                if (!subject.includes(subjectFilter)) show = false;
            }
            if (classFilter) {
                const classData = row.dataset.class || '';
                if (classData !== classFilter) show = false;
            }
            if (streamFilter) {
                const streamData = row.dataset.stream || '';
                if (streamData.toLowerCase() !== streamFilter.toLowerCase()) show = false;
            }
            if (yearFilter) {
                const yearData = row.dataset.year || '';
                if (!yearData.includes(yearFilter)) show = false;
            }
            
            row.style.display = show ? '' : 'none';
            if (show) visibleCount++;
        }
    });
    
    const countEl = document.getElementById('filteredRowCount');
    if (countEl) {
        if (visibleCount === 0) {
            countEl.textContent = 'No matching records';
        } else if (visibleCount === total) {
            countEl.textContent = `Total: ${total} records`;
        } else {
            countEl.textContent = `Showing ${visibleCount} of ${total} records`;
        }
    }
}

function clearMarksFilters() {
    document.getElementById('filterStudent').value = '';
    document.getElementById('filterSubject').value = '';
    document.getElementById('filterClass').value = '';
    document.getElementById('filterStream').value = '';
    document.getElementById('filterYear').value = '';
    applyMarksFilters();
}

// ============================================
// LOAD SUBJECTS FROM DATABASE
// ============================================

async function loadSubjectsFromDB() {
    try {
        console.log("🔄 Loading subjects from database...");
        
        const { data: olevelData, error: olevelError } = await sb
            .from('subjects')
            .select('name, category')
            .eq('level', 'olevel')
            .order('name', { ascending: true });
        
        if (!olevelError && olevelData && olevelData.length > 0) {
            dbOlevelSubjects = olevelData.map(s => s.name);
            console.log(`✅ O-Level: ${dbOlevelSubjects.length} subjects`);
        } else {
            dbOlevelSubjects = ['Mathematics', 'English', 'Physics', 'Chemistry', 'Biology'];
            console.warn("No O-Level subjects found, using defaults");
        }
        
        const { data: alevelData, error: alevelError } = await sb
            .from('subjects')
            .select('name, category')
            .eq('level', 'alevel')
            .order('name', { ascending: true });
        
        if (!alevelError && alevelData && alevelData.length > 0) {
            dbAlevelPrincipalSubjects = alevelData.map(s => s.name);
            console.log(`✅ A-Level Principal: ${dbAlevelPrincipalSubjects.length} subjects`);
        } else {
            dbAlevelPrincipalSubjects = ['Mathematics', 'Physics', 'Chemistry', 'Biology', 'Economics', 'History', 'Geography'];
            console.warn("No A-Level subjects found, using defaults");
        }
        
        const { data: subsidiaryData, error: subsidiaryError } = await sb
            .from('subsidiary_subjects')
            .select('subject_name')
            .order('subject_name', { ascending: true });
        
        if (!subsidiaryError && subsidiaryData && subsidiaryData.length > 0) {
            dbAlevelSubsidiarySubjects = subsidiaryData.map(s => s.subject_name);
            console.log(`✅ A-Level Subsidiary: ${dbAlevelSubsidiarySubjects.length} subjects`);
        } else {
            dbAlevelSubsidiarySubjects = ['General Paper', 'ICT', 'Subsidiary Mathematics'];
            console.warn("No subsidiary subjects found, using defaults");
        }
        
        return true;
    } catch (error) {
        console.error('Error loading subjects:', error);
        dbOlevelSubjects = ['Mathematics', 'English', 'Physics', 'Chemistry', 'Biology'];
        dbAlevelPrincipalSubjects = ['Mathematics', 'Physics', 'Chemistry', 'Biology'];
        dbAlevelSubsidiarySubjects = ['General Paper', 'ICT'];
        return false;
    }
}

// ============================================
// LOAD GRADING RULES
// ============================================

async function loadGradingRules() {
    try {
        if (currentLevel === 'olevel') {
            const { data, error } = await sb
                .from('olevel_grades')
                .select('*')
                .order('points', { ascending: true });
            
            if (error) throw error;
            gradingRules.olevel = data || [];
        } else {
            const [principal, subsidiary] = await Promise.all([
                sb.from('alevel_principal_grades').select('*').order('points', { ascending: false }),
                sb.from('alevel_subsidiary_grades').select('*').order('points', { ascending: false })
            ]);
            
            if (principal.error) throw principal.error;
            if (subsidiary.error) throw subsidiary.error;
            
            gradingRules.alevel = {
                principal: principal.data || [],
                subsidiary: subsidiary.data || []
            };
        }
        return true;
    } catch (error) {
        console.error('Error loading grading rules:', error);
        return false;
    }
}

// ============================================
// CALCULATE GRADE FROM SETTINGS
// ============================================

function calculateGrade(percentage, isSubsidiary = false) {
    let rules = [];
    
    if (currentLevel === 'olevel') {
        rules = gradingRules.olevel;
    } else {
        rules = isSubsidiary ? gradingRules.alevel.subsidiary : gradingRules.alevel.principal;
    }
    
    if (rules && rules.length > 0) {
        for (const rule of rules) {
            if (percentage >= rule.min_percentage && percentage <= rule.max_percentage) {
                return {
                    grade: rule.grade,
                    points: rule.points,
                    color: rule.color_code || '#2ecc71',
                    remark: rule.remark || ''
                };
            }
        }
    }
    
    // Fallback grading
    if (currentLevel === 'olevel') {
        if (percentage >= 90) return { grade: 'A', points: 1, color: '#2ecc71', remark: 'Excellent' };
        if (percentage >= 80) return { grade: 'B', points: 2, color: '#3498db', remark: 'Very Good' };
        if (percentage >= 70) return { grade: 'C', points: 3, color: '#f39c12', remark: 'Good' };
        if (percentage >= 60) return { grade: 'D', points: 4, color: '#e67e22', remark: 'Credit' };
        if (percentage >= 50) return { grade: 'E', points: 5, color: '#e74c3c', remark: 'Pass' };
        return { grade: 'F', points: 6, color: '#c0392b', remark: 'Fail' };
    } else {
        if (isSubsidiary) {
            if (percentage >= 80) return { grade: 'A', points: 6, color: '#2ecc71', remark: 'Excellent' };
            if (percentage >= 70) return { grade: 'B', points: 5, color: '#3498db', remark: 'Very Good' };
            if (percentage >= 60) return { grade: 'C', points: 4, color: '#f39c12', remark: 'Good' };
            if (percentage >= 50) return { grade: 'D', points: 3, color: '#e67e22', remark: 'Credit' };
            if (percentage >= 40) return { grade: 'E', points: 2, color: '#e74c3c', remark: 'Pass' };
            return { grade: 'O', points: 1, color: '#95a5a6', remark: 'Ordinary' };
        } else {
            if (percentage >= 80) return { grade: 'A', points: 6, color: '#2ecc71', remark: 'Excellent' };
            if (percentage >= 70) return { grade: 'B', points: 5, color: '#3498db', remark: 'Very Good' };
            if (percentage >= 60) return { grade: 'C', points: 4, color: '#f39c12', remark: 'Good' };
            if (percentage >= 50) return { grade: 'D', points: 3, color: '#e67e22', remark: 'Credit' };
            if (percentage >= 40) return { grade: 'E', points: 2, color: '#e74c3c', remark: 'Pass' };
            return { grade: 'O', points: 1, color: '#95a5a6', remark: 'Ordinary' };
        }
    }
}

// ============================================
// O-LEVEL GRADE DESCRIPTOR
// ============================================

function getOlevelGradeDescriptor(total100) {
    total100 = Math.min(100, Math.max(0, total100));
    
    if (gradingRules.olevel && gradingRules.olevel.length > 0) {
        for (const rule of gradingRules.olevel) {
            if (total100 >= rule.min_percentage && total100 <= rule.max_percentage) {
                return {
                    grade: rule.grade,
                    descriptor: rule.remark || '',
                    color: rule.color_code || '#2ecc71'
                };
            }
        }
    }
    
    if (total100 >= 85) return { grade: 'A', descriptor: 'Exceptional', color: '#2ecc71' };
    if (total100 >= 70) return { grade: 'B', descriptor: 'Outstanding', color: '#3498db' };
    if (total100 >= 60) return { grade: 'C', descriptor: 'Satisfactory', color: '#f39c12' };
    if (total100 >= 40) return { grade: 'D', descriptor: 'Basic', color: '#e67e22' };
    return { grade: 'E', descriptor: 'Elementary', color: '#e74c3c' };
}

// ============================================
// LOAD ALL MARKS DATA
// ============================================

// ============================================
// LOAD ALL MARKS DATA - WITH PAGINATION (NO 1000 LIMIT)
// ============================================

async function loadAllMarks() {
    try {
        await loadGradingRules();
        
        // ✅ Load students first
        const studentsRes = await sb
            .from('students')
            .select('*')
            .in('class', currentLevel === 'olevel' ? ['S.1', 'S.2', 'S.3', 'S.4'] : ['S.5', 'S.6'])
            .order('name');
        
        if (studentsRes.error) throw studentsRes.error;
        allStudentsList = studentsRes.data || [];
        
        // ✅ Load ALL marks with pagination
        let allMarks = [];
        let page = 0;
        const pageSize = 1000;
        let hasMore = true;
        
        while (hasMore) {
            const { data, error } = await sb
                .from('marks')
                .select('*')
                .eq('level', currentLevel)
                .order('created_at', { ascending: false })
                .range(page * pageSize, (page + 1) * pageSize - 1);
            
            if (error) throw error;
            
            if (data && data.length > 0) {
                allMarks = allMarks.concat(data);
                page++;
                if (data.length < pageSize) {
                    hasMore = false;
                }
                console.log(`📥 Loaded ${allMarks.length} marks so far...`);
            } else {
                hasMore = false;
            }
        }
        
        allMarksList = allMarks;
        
        // ✅ Add student names to marks for delete function
        for (const mark of allMarksList) {
            const student = allStudentsList.find(s => s.id === mark.student_id);
            if (student) {
                mark.student_name = student.name;
            } else {
                mark.student_name = 'Unknown';
            }
        }
        
        console.log(`✅ Loaded ${allMarksList.length} marks and ${allStudentsList.length} students`);
        return true;
    } catch (error) {
        console.error('Error loading data:', error);
        return false;
    }
}
