function getClassOptions() {
    return currentLevel === 'olevel' ? ['S.1', 'S.2', 'S.3', 'S.4'] : ['S.5', 'S.6'];
}

function getStreamOptions() {
    return STREAM_OPTIONS[currentLevel];
}

