// ============================================
// PROCESS PAYMENT
// ============================================

async function processPaymentWithCarryForward(studentId, amount, feeType, method, paymentDate, term, year, remarks, sendSms = true) {
    const student = allStudentsList.find(s => s.id === studentId);
    if (!student) throw new Error('Student not found');
    
    const termFee = getStudentFeeAmount(student);
    if (termFee === null) throw new Error(`No fee structure found for ${student.name}`);
    
    const receiptNo = generateReceiptNo();
    
    const { data, error } = await sb
        .from('payments')
        .insert({
            student_id: studentId,
            fee_type: feeType,
            amount: amount,
            payment_method: method,
            receipt_no: receiptNo,
            payment_date: paymentDate,
            term: term,
            year: year,
            remarks: remarks,
            send_sms: sendSms,   // use the parameter
            created_at: new Date().toISOString()
        })
        .select();
    
    if (error) throw error;
    
    await getPayments();
    
    return { receiptNo: receiptNo };
}

