// Helper to generate current local datetime string with seconds
function getLocalDateTimeInput() {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const seconds = String(now.getSeconds()).padStart(2, '0');
    return `${year}-${month}-${day}T${hours}:${minutes}:${seconds}`;
}

window.showAddPaymentModal = async function() {
    console.log("Opening Add Payment Modal...");
    
    await loadFeeStructure();
    await getStudentsForPayments();
    await getPayments();
    
    let filteredStudents = getStudentsByLevel();
    filteredStudents = filteredStudents.sort((a, b) => a.name.localeCompare(b.name));
    
    const currentYear = new Date().getFullYear().toString();
    const currentTerm = getCurrentTerm();
    
    if (filteredStudents.length === 0) {
        Swal.fire('No Students', `No ${currentLevel.toUpperCase()} students found.`, 'info');
        return;
    }
    
    let studentOptions = '<option value="">-- Select Student --</option>';
    for (const s of filteredStudents) {
        const fee = getStudentFeeAmount(s);
        const feeDisplay = fee ? formatMoney(fee) : '⚠️ No Fee Set';
        studentOptions += `<option value="${s.id}" data-fee="${fee || 0}">${escapeHtml(s.name)} (${s.class}) - ${s.admission_no || 'No ADM'} - Fee: ${feeDisplay}</option>`;
    }
    
    const { value: result } = await Swal.fire({
        title: `<i class="fas fa-credit-card"></i> Record Payment - ${currentLevel.toUpperCase()}`,
        html: `
            <div class="text-start">
                <div class="alert alert-info small mb-3">
                    <i class="fas fa-database"></i> <strong>Live Data:</strong> Fees loaded from fee_structure table
                </div>
                
                <div class="mb-3">
                    <label class="form-label fw-bold">👨‍🎓 Select Student *</label>
                    <select id="paymentStudentSelect" class="form-select" style="width: 100%;">
                        ${studentOptions}
                    </select>
                    <small class="text-muted">Click and type to search - ${filteredStudents.length} students available</small>
                </div>
                
                <div id="balanceInfo" class="alert alert-info mb-3" style="display: none;">
                    <strong>💰 Fee & Balance Information:</strong>
                    <div id="balanceDetails" style="margin-top: 8px;"></div>
                </div>
                
                <div class="row mb-3">
                    <div class="col-md-6">
                        <label class="form-label fw-bold">Fee Type</label>
                        <select id="feeTypeSelect" class="form-select">
                            <option value="Tuition Fee">Tuition Fee</option>
                            <option value="Development Fee">Development Fee</option>
                            <option value="Activity Fee">Activity Fee</option>
                            <option value="Library Fee">Library Fee</option>
                            <option value="Sports Fee">Sports Fee</option>
                            <option value="Meals Fee">Meals Fee</option>
                            <option value="Accommodation">Accommodation</option>
                            <option value="Other">Other</option>
                        </select>
                    </div>
                    <div class="col-md-6">
                        <label class="form-label fw-bold">Amount (UGX) *</label>
                        <input type="number" id="amountInput" class="form-control" placeholder="0" min="0" step="1000">
                    </div>
                </div>
                
                <div class="row mb-3">
                    <div class="col-md-6">
                        <label class="form-label fw-bold">Payment Method</label>
                        <select id="methodSelect" class="form-select">
                            <option value="Cash">💵 Cash</option>
                            <option value="Bank Transfer">🏦 Bank Transfer</option>
                            <option value="Mobile Money">📱 Mobile Money</option>
                            <option value="Cheque">📝 Cheque</option>
                        </select>
                    </div>
                    <div class="col-md-6">
                        <label class="form-label fw-bold">Receipt No</label>
                        <input type="text" id="receiptNoInput" class="form-control" value="${generateReceiptNo()}" readonly>
                    </div>
                </div>
                
                <!-- ✅ DATETIME PICKER with seconds -->
                <div class="row mb-3">
                    <div class="col-md-6">
                        <label class="form-label fw-bold">Payment Date & Time *</label>
                        <input type="datetime-local" id="paymentDateInput" class="form-control" 
                               value="${getLocalDateTimeInput()}" step="1">   <!-- step="1" enables seconds -->
                    </div>
                    <div class="col-md-6">
                        <label class="form-label fw-bold">Term</label>
                        <select id="termSelect" class="form-select">
                            <option value="Term 1" ${currentTerm === 'Term 1' ? 'selected' : ''}>Term 1</option>
                            <option value="Term 2" ${currentTerm === 'Term 2' ? 'selected' : ''}>Term 2</option>
                            <option value="Term 3" ${currentTerm === 'Term 3' ? 'selected' : ''}>Term 3</option>
                        </select>
                    </div>
                </div>
                
                <div class="row mb-3">
                    <div class="col-md-6">
                        <label class="form-label fw-bold">Year</label>
                        <input type="text" id="yearInput" class="form-control" value="${currentYear}">
                    </div>
                </div>
                
                <div class="mb-3">
                    <label class="form-label fw-bold">Remarks</label>
                    <textarea id="remarksInput" class="form-control" rows="2"></textarea>
                </div>
                
                <div class="form-check mb-3">
                    <input type="checkbox" class="form-check-input" id="sendSmsCheckbox" checked>
                    <label class="form-check-label fw-bold">📱 Send SMS notification to parent</label>
                    <small class="text-muted d-block">Uncheck to skip sending SMS for this payment.</small>
                </div>
                
                <div class="alert alert-success small">
                    <i class="fas fa-info-circle"></i> 
                    <strong>Note:</strong> Excess payment automatically carries forward to next term.
                </div>
                
                <div class="text-end mt-2">
                    <button type="button" class="btn btn-sm btn-outline-secondary" onclick="refreshModalFees()">
                        <i class="fas fa-sync-alt"></i> Refresh Fees
                    </button>
                </div>
            </div>
        `,
        width: '680px',
        showCancelButton: true,
        confirmButtonText: '<i class="fas fa-save"></i> Save Payment',
        didOpen: () => {
            const studentSelect = document.getElementById('paymentStudentSelect');
            const balanceInfo = document.getElementById('balanceInfo');
            const balanceDetails = document.getElementById('balanceDetails');
            const termSelect = document.getElementById('termSelect');
            const yearInput = document.getElementById('yearInput');
            
            const updateBalanceInfo = async () => {
                const studentId = studentSelect.value;
                const term = termSelect.value;
                const year = yearInput.value;
                
                if (!studentId) {
                    balanceInfo.style.display = 'none';
                    return;
                }
                
                balanceInfo.style.display = 'block';
                balanceDetails.innerHTML = '<div class="text-center"><i class="fas fa-spinner fa-spin"></i> Loading latest fee data...</div>';
                
                try {
                    await loadFeeStructure();
                    await getPayments();
                    
                    const status = await calculateStudentFeeStatusWithCarryForward(studentId, year, term);
                    
                    if (!status || status.status === 'NO_FEE') {
                        balanceDetails.innerHTML = `
                            <div class="alert alert-warning text-center">
                                <i class="fas fa-exclamation-triangle"></i> 
                                <strong>No fee structure found!</strong><br>
                                Please add fee in Settings → Fee Structure
                            </div>
                        `;
                        return;
                    }
                    
                    balanceDetails.innerHTML = `
                        <div class="small">
                            <div><strong>👨‍🎓 Student:</strong> ${escapeHtml(status.student.name)}</div>
                            <div><strong>📚 Class:</strong> ${status.student.class}</div>
                            <div><strong>🏠 Type:</strong> ${status.student.student_type || 'Day'}</div>
                            <hr class="my-1">
                            <div><strong>💰 Term Fee:</strong> ${formatMoney(status.termFee)}</div>
                            ${status.previousTermsBalance > 0 ? `<div class="text-warning"><strong>⚠️ Previous Balance:</strong> ${formatMoney(status.previousTermsBalance)}</div>` : ''}
                            <hr class="my-1">
                            <div><strong>💸 Paid This Term:</strong> ${formatMoney(status.currentTermPaid)}</div>
                            <div><strong class="${status.balance > 0 ? 'text-danger' : 'text-success'}">💰 Current Balance: ${formatMoney(Math.abs(status.balance))} ${status.balance > 0 ? '(Due)' : '(Credit)'}</strong></div>
                            <div class="text-muted small mt-2"><i class="fas fa-database"></i> Data from database @ ${new Date().toLocaleTimeString()}</div>
                        </div>
                    `;
                } catch (error) {
                    balanceDetails.innerHTML = `<div class="alert alert-danger">Error loading data</div>`;
                }
            };
            
            studentSelect.onchange = updateBalanceInfo;
            termSelect.onchange = updateBalanceInfo;
            yearInput.onchange = updateBalanceInfo;
            
            if (studentSelect.value) {
                setTimeout(updateBalanceInfo, 100);
            }
        },
        preConfirm: async () => {
            const studentId = document.getElementById('paymentStudentSelect').value;
            const amount = parseInt(document.getElementById('amountInput').value) || 0;
            
            if (!studentId) {
                Swal.showValidationMessage('Please select a student!');
                return false;
            }
            if (amount <= 0) {
                Swal.showValidationMessage('Please enter a valid amount!');
                return false;
            }
            
            const sendSms = document.getElementById('sendSmsCheckbox').checked;
            const paymentDateTime = document.getElementById('paymentDateInput').value; // format: YYYY-MM-DDThh:mm:ss
            
            // Validate that datetime includes seconds (optional, but step=1 ensures it)
            if (!paymentDateTime || paymentDateTime.length < 19) {
                Swal.showValidationMessage('Please select a valid date and time (including seconds).');
                return false;
            }
            
            return {
                student_id: studentId,
                amount: amount,
                fee_type: document.getElementById('feeTypeSelect').value,
                method: document.getElementById('methodSelect').value,
                payment_date: paymentDateTime,
                term: document.getElementById('termSelect').value,
                year: document.getElementById('yearInput').value,
                remarks: document.getElementById('remarksInput').value || '',
                send_sms: sendSms
            };
        }
    });
    
    if (result) {
        Swal.fire({ title: 'Processing...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });
        try {
            await processPaymentWithCarryForward(
                result.student_id,
                result.amount,
                result.fee_type,
                result.method,
                result.payment_date,   // full timestamp with seconds
                result.term,
                result.year,
                result.remarks,
                result.send_sms
            );
            Swal.fire('✅ Success!', 'Payment recorded successfully.', 'success');
            await refreshPayments();
        } catch (error) {
            Swal.fire('Error!', error.message, 'error');
        }
    }
};
// ============================================
// REFRESH MODAL FEES
// ============================================

window.refreshModalFees = async function() {
    feeStructure = {};
    await loadFeeStructure();
    await getPayments();
    
    const studentSelect = document.getElementById('paymentStudentSelect');
    if (studentSelect && studentSelect.value) {
        const termSelect = document.getElementById('termSelect');
        const yearInput = document.getElementById('yearInput');
        const status = await calculateStudentFeeStatusWithCarryForward(
            studentSelect.value, 
            yearInput?.value || new Date().getFullYear().toString(),
            termSelect?.value || getCurrentTerm()
        );
        
        const balanceDetails = document.getElementById('balanceDetails');
        if (balanceDetails) {
            if (status.status === 'NO_FEE') {
                balanceDetails.innerHTML = `
                    <div class="alert alert-warning text-center">
                        <i class="fas fa-exclamation-triangle"></i> 
                        <strong>Fees refreshed!</strong> Still no fee found.
                    </div>
                `;
            } else {
                balanceDetails.innerHTML = `
                    <div class="small text-success">
                        <i class="fas fa-check-circle"></i> <strong>Fees refreshed!</strong><br>
                        Term Fee: ${formatMoney(status.termFee)}<br>
                        Balance: ${formatMoney(Math.abs(status.balance))} ${status.balance > 0 ? '(Due)' : '(Credit)'}
                    </div>
                `;
            }
        }
    }
    
    Swal.fire('Refreshed!', 'Fees reloaded from database', 'success');
};

// ============================================
// VIEW PAYMENT HISTORY
// ============================================

window.viewPaymentHistory = async function(studentId) {
    await getPayments();
    await getStudentsForPayments();
    
    const student = allStudentsList.find(s => s.id === studentId);
    if (!student) return;
    
    const studentPayments = allPaymentsList.filter(p => p.student_id === studentId);
    
    if (studentPayments.length === 0) {
        Swal.fire('No Payments', `${student.name} has no payment records.`, 'info');
        return;
    }
    
    const totalPaid = studentPayments.reduce((sum, p) => sum + p.amount, 0);
    
    let html = `
        <div class="text-start">
            <div class="card bg-light mb-3">
                <div class="card-body">
                    <p><strong>Student:</strong> ${escapeHtml(student.name)}</p>
                    <p><strong>Class:</strong> ${student.class}</p>
                    <p><strong>Total Paid:</strong> ${formatMoney(totalPaid)}</p>
                </div>
            </div>
            <div class="table-responsive">
                <table class="table table-bordered">
                    <thead class="table-primary">
                        <tr><th>Date</th><th>Receipt No</th><th>Amount</th><th>Method</th><th>Term</th><th>Year</th></tr>
                    </thead>
                    <tbody>
    `;
    
    for (const p of studentPayments) {
        html += `
            <tr>
                <td>${p.payment_date || '-'}</td>
                <td>${p.receipt_no || '-'}</td>
                <td class="text-end">${formatMoney(p.amount)}</span></td>
                <td>${p.payment_method || '-'}</td>
                <td>${p.term || '-'}</td>
                <td>${p.year || '-'}</td>
            </tr>
        `;
    }
    
    html += `</tbody></tr></div></div>`;
    
    Swal.fire({
        title: `Payment History - ${escapeHtml(student.name)}`,
        html: html,
        width: '700px',
        confirmButtonText: 'Close'
    });
};

// ============================================
// PRINT RECEIPT
// ============================================

window.printReceipt = async function(id) {
    await loadSchoolSettingsForPayments();
    await getStudentsForPayments();

    const payment = allPaymentsList.find(p => p.id === id);
    if (!payment) return;

    const student = allStudentsList.find(s => s.id === payment.student_id);
    if (!student) return;

    const logoUrl = schoolSettings.school_logo || '';
    const printWindow = window.open('', '_blank', 'width=600,height=800');

    const formatMoney = (amount) => `UGX ${(amount || 0).toLocaleString()}`;
    const escapeHtml = (text) =>
        (text || '').replace(/[&<>]/g, (m) => ({
            '&': '&amp;',
            '<': '&lt;',
            '>': '&gt;'
        }[m]));

    // ✅ NEW: Display raw database timestamp (no timezone conversion)
    const formatDateTime = (dateString) => {
        if (!dateString) return '-';
        // Remove 'T' and milliseconds/timezone for clean display
        return dateString.replace('T', ' ').replace(/\.\d+/, '').replace(/[+-]\d{2}:\d{2}$/, '');
    };

    // ✅ Use payment_date (the legal timestamp), not created_at
    const receiptTimestamp = payment.payment_date;

    const html = `
        <!DOCTYPE html>
        <html>
        <head>
            <meta charset="UTF-8">
            <title>Receipt - ${payment.receipt_no}</title>
            <style>
                body {
                    font-family: "Segoe UI", Arial, sans-serif;
                    padding: 20px;
                    background: #f4f4f4;
                    margin: 0;
                }
                .receipt {
                    max-width: 380px;
                    margin: auto;
                    background: #fff;
                    border: 2px solid #01605a;
                    border-radius: 12px;
                    padding: 20px;
                    position: relative;
                    overflow: hidden;
                }
                .watermark {
                    position: absolute;
                    top: 50%;
                    left: 50%;
                    transform: translate(-50%, -50%);
                    width: 65%;
                    height: 65%;
                    background-image: url('${logoUrl}');
                    background-repeat: no-repeat;
                    background-position: center;
                    background-size: contain;
                    opacity: 0.18;
                    z-index: 0;
                }
                .content {
                    position: relative;
                    z-index: 1;
                }
                .header {
                    text-align: center;
                    border-bottom: 2px solid #ff862d;
                    padding-bottom: 10px;
                    margin-bottom: 15px;
                }
                .school-name {
                    font-size: 18px;
                    font-weight: 700;
                    color: #01605a;
                }
                .receipt-title {
                    font-size: 14px;
                    font-weight: 600;
                }
                .receipt-no {
                    font-size: 13px;
                    background: #f2f2f2;
                    padding: 6px;
                    margin: 10px 0;
                    text-align: center;
                    border-radius: 6px;
                    font-family: monospace;
                }
                table {
                    width: 100%;
                    font-size: 13px;
                }
                td {
                    padding: 4px 0;
                }
                td:first-child {
                    font-weight: 600;
                }
                .total {
                    border-top: 1px dashed #ccc;
                    margin-top: 10px;
                    padding-top: 8px;
                    font-size: 14px;
                    font-weight: bold;
                    text-align: right;
                }
                .signature {
                    display: flex;
                    justify-content: space-between;
                    margin-top: 25px;
                    font-size: 12px;
                }
                .line {
                    border-bottom: 1px solid #000;
                    height: 20px;
                    margin-bottom: 5px;
                }
                .paid-stamp {
                    margin-top: 12px;
                    text-align: center;
                    border: 2px solid #d32f2f;
                    color: #d32f2f;
                    font-size: 20px;
                    font-weight: 700;
                    padding: 6px 14px;
                    display: inline-block;
                    border-radius: 6px;
                    letter-spacing: 2px;
                }
                .thankyou {
                    text-align: center;
                    margin-top: 10px;
                    font-size: 13px;
                    color: #01605a;
                    font-weight: 600;
                }
                @media print {
                    body {
                        background: white;
                        padding: 0;
                    }
                    .no-print {
                        display: none;
                    }
                }
            </style>
        </head>
        <body>
            <div class="receipt">
                ${logoUrl ? `<div class="watermark"></div>` : ''}
                <div class="content">
                    ${logoUrl ? `<div style="text-align:center; margin-bottom:10px;"><img src="${logoUrl}" style="max-height:70px; object-fit:contain;" /></div>` : ''}
                    
                    <div class="header">
                        <div class="school-name">${escapeHtml(schoolSettings.school_name || 'UGANDA SCHOOL SYSTEM')}</div>
                        <div class="receipt-title">OFFICIAL PAYMENT RECEIPT</div>
                    </div>

                    <div class="receipt-no">
                        Receipt No: ${payment.receipt_no}
                    </div>

                    <table>
                        <tr>
                            <td width="40%">Date & Time</td>
                            <td>${receiptTimestamp ? formatDateTime(receiptTimestamp) : 'MISSING'}</td>
                        </tr>
                        <tr><td>Student</td><td>${escapeHtml(student.name)}</td></tr>
                        <tr><td>Class</td><td>${student.class}</td></tr>
                        <tr><td>Admission</td><td>${student.admission_no || '-'}</td></tr>
                        <tr><td>Parent</td><td>${escapeHtml(student.parent_name || '-')}</td></tr>
                        <tr><td>Fee Type</td><td>${payment.fee_type}</td></tr>
                        <tr><td>Method</td><td>${payment.payment_method}</td></tr>
                        <tr><td>Term</td><td>${payment.term} ${payment.year}</td></tr>
                    </table>

                    <div class="total">
                        Total: ${formatMoney(payment.amount)}
                    </div>

                    <div class="signature">
                        <div><div class="line"></div>Parent</div>
                        <div><div class="line"></div>${escapeHtml(schoolSettings.bursar_name || 'Bursar')}</div>
                    </div>

                    ${payment.status === 'paid' || payment.amount > 0 ? `
                        <div style="text-align:center;">
                            <div class="paid-stamp">PAID</div>
                        </div>
                    ` : ''}

                    <div class="thankyou">Thank you for your payment</div>
                </div>
            </div>
            <div class="no-print" style="text-align:center; margin-top:20px;">
                <button onclick="window.print()">🖨️ Print</button>
                <button onclick="window.close()">❌ Close</button>
            </div>
        </body>
        </html>
    `;

    printWindow.document.write(html);
    printWindow.document.close();

    setTimeout(() => {
        printWindow.print();
    }, 500);
};
// ============================================
// VERIFY SUPER ADMIN PASSWORD (For Payment Module)
// ============================================

async function verifySuperAdminPasswordForPayment() {
    return new Promise((resolve) => {
        Swal.fire({
            title: '🔐 Super Admin Authorization Required',
            html: `
                <div class="text-start">
                    <div class="alert alert-danger mb-3">
                        <i class="fas fa-shield-alt"></i> 
                        <strong>Authorization Required!</strong><br>
                        Deleting payment records requires Super Administrator approval.
                    </div>
                    <div class="mb-3">
                        <label class="form-label fw-bold">Super Admin Password</label>
                        <input type="password" id="superAdminPassword" class="form-control" 
                               placeholder="Enter Super Admin password" autocomplete="off">
                        <small class="text-muted">A Super Admin must authorize this deletion.</small>
                    </div>
                    <div id="passwordError" class="alert alert-danger small" style="display: none;">
                        <i class="fas fa-exclamation-triangle"></i> Incorrect Super Admin password. Access denied.
                    </div>
                </div>
            `,
            width: '450px',
            showCancelButton: true,
            confirmButtonText: '<i class="fas fa-check"></i> Authorize Deletion',
            cancelButtonText: '<i class="fas fa-times"></i> Cancel',
            confirmButtonColor: '#d33',
            allowOutsideClick: false,
            didOpen: () => {
                const passwordInput = document.getElementById('superAdminPassword');
                if (passwordInput) {
                    passwordInput.focus();
                    passwordInput.addEventListener('keypress', (e) => {
                        if (e.key === 'Enter') {
                            Swal.clickConfirm();
                        }
                    });
                }
            },
            preConfirm: async () => {
                const password = document.getElementById('superAdminPassword')?.value;
                
                if (!password) {
                    Swal.showValidationMessage('Please enter Super Admin password');
                    return false;
                }
                
                try {
                    // Get super admin email from users table
                    const { data: superAdminData, error: superAdminError } = await sb
                        .from('users')
                        .select('email')
                        .eq('role', 'superadmin')
                        .limit(1)
                        .single();
                    
                    if (superAdminError) {
                        Swal.showValidationMessage('Could not verify Super Admin credentials');
                        return false;
                    }
                    
                    // Verify password with Supabase
                    const { data, error } = await sb.auth.signInWithPassword({
                        email: superAdminData.email,
                        password: password
                    });
                    
                    if (error) {
                        const errorDiv = document.getElementById('passwordError');
                        if (errorDiv) errorDiv.style.display = 'block';
                        Swal.showValidationMessage('Incorrect Super Admin password');
                        return false;
                    }
                    
                    return true;
                } catch (err) {
                    Swal.showValidationMessage('Verification failed. Please try again.');
                    return false;
                }
            }
        }).then((result) => {
            resolve(result.isConfirmed);
        });
    });
}

// ============================================
// CHECK IF USER CAN DELETE PAYMENTS
// ============================================

function canDeletePayments() {
    // Super Admin can delete without password
    if (currentUserRole === 'superadmin') return true;
    // Admin and Accountant can delete but need password
    if (currentUserRole === 'admin' || currentUserRole === 'accountant') return true;
    // Others cannot delete
    return false;
}

function needsPasswordForDelete() {
    // Admin and Accountant need password verification
    return (currentUserRole === 'admin' || currentUserRole === 'accountant');
}

// ============================================
// DELETE PAYMENT
// ============================================

// ============================================
// DELETE PAYMENT - WITH ROLE-BASED PASSWORD
// ============================================

window.deletePaymentItem = async function(id) {
    // Check if user has delete permission
    if (!canDeletePayments()) {
        Swal.fire({
            title: '⛔ Access Denied',
            text: 'You do not have permission to delete payment records.',
            icon: 'error',
            confirmButtonText: 'OK'
        });
        return;
    }
    
    const isSuperAdmin = (currentUserRole === 'superadmin');
    const needsPassword = needsPasswordForDelete();
    const payment = allPaymentsList.find(p => p.id === id);
    const student = allStudentsList.find(s => s.id === payment?.student_id);
    
    if (!payment) return;
    
    // First confirmation
    const confirmDelete = await Swal.fire({
        title: 'Delete Payment Record?',
        html: `<p>Are you sure you want to delete this payment record?</p>
               <div class="text-start">
                   <p><strong>💰 Amount:</strong> ${formatMoney(payment.amount)}</p>
                   <p><strong>👨‍🎓 Student:</strong> ${student ? escapeHtml(student.name) : 'Unknown'}</p>
                   <p><strong>📅 Date:</strong> ${payment.payment_date || '-'}</p>
                   <p><strong>📝 Receipt No:</strong> ${payment.receipt_no || '-'}</p>
               </div>
               <p class="text-danger mt-2"><strong>⚠️ THIS ACTION CANNOT BE UNDONE!</strong></p>
               ${needsPassword ? '<p class="text-warning"><i class="fas fa-exclamation-triangle"></i> Super Admin authorization will be required to proceed.</p>' : ''}`,
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        confirmButtonText: '<i class="fas fa-trash"></i> Yes, Delete',
        cancelButtonText: '<i class="fas fa-times"></i> Cancel'
    });
    
    if (!confirmDelete.isConfirmed) return;
    
    // If not Super Admin (Admin or Accountant), verify Super Admin password
    if (needsPassword) {
        const passwordVerified = await verifySuperAdminPasswordForPayment();
        if (!passwordVerified) {
            Swal.fire({
                title: '⛔ Access Denied',
                text: 'Super Admin authorization failed. Delete operation cancelled.',
                icon: 'error',
                confirmButtonText: 'OK'
            });
            return;
        }
    }
    
    // Final confirmation
    const finalConfirm = await Swal.fire({
        title: '🔴 Final Confirmation',
        html: `<p>${needsPassword ? 'Super Admin authorized. ' : ''}Are you absolutely sure you want to delete this payment record?</p>
               <p><strong>Amount:</strong> ${formatMoney(payment.amount)}</p>
               <p><strong>Student:</strong> ${student ? escapeHtml(student.name) : 'Unknown'}</p>
               <p><strong>Receipt No:</strong> ${payment.receipt_no || '-'}</p>
               <p class="text-danger">This action cannot be undone!</p>`,
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        confirmButtonText: 'Yes, Delete Permanently',
        cancelButtonText: 'Cancel'
    });
    
    if (finalConfirm.isConfirmed) {
        Swal.fire({ 
            title: 'Deleting...', 
            text: 'Removing payment record...',
            allowOutsideClick: false, 
            didOpen: () => Swal.showLoading() 
        });
        
        try {
            await deletePayment(id);
            Swal.fire({
                title: '✅ Deleted!',
                text: 'Payment record has been deleted successfully.',
                icon: 'success',
                timer: 1500,
                showConfirmButton: false
            });
            await refreshPayments();
        } catch (error) {
            Swal.fire({
                title: '❌ Error!',
                text: error.message,
                icon: 'error',
                confirmButtonText: 'OK'
            });
        }
    }
};
// ============================================
// BULK DELETE PAYMENTS
// ============================================

// ============================================
// BULK DELETE PAYMENTS - WITH ROLE-BASED PASSWORD
// ============================================

window.bulkDeletePayments = async function() {
    // Check if user has delete permission
    if (!canDeletePayments()) {
        Swal.fire({
            title: '⛔ Access Denied',
            text: 'You do not have permission to delete payment records.',
            icon: 'error',
            confirmButtonText: 'OK'
        });
        return;
    }
    
    const isSuperAdmin = (currentUserRole === 'superadmin');
    const needsPassword = needsPasswordForDelete();
    const checkboxes = document.querySelectorAll('.paymentCheck:checked');
    const ids = Array.from(checkboxes).map(cb => cb.dataset.id);
    
    if (ids.length === 0) {
        Swal.fire('Error', 'No payments selected', 'error');
        return;
    }
    
    // Calculate total amount of selected payments
    let totalAmount = 0;
    for (const id of ids) {
        const payment = allPaymentsList.find(p => p.id === id);
        if (payment) totalAmount += payment.amount || 0;
    }
    
    // First confirmation
    const confirmDelete = await Swal.fire({
        title: `Delete ${ids.length} Payment Records?`,
        html: `<p>You are about to delete <strong>${ids.length}</strong> payment records.</p>
               <p><strong>💰 Total Amount:</strong> ${formatMoney(totalAmount)}</p>
               <p class="text-danger"><strong>⚠️ THIS ACTION CANNOT BE UNDONE!</strong></p>
               ${needsPassword ? '<p class="text-warning"><i class="fas fa-exclamation-triangle"></i> Super Admin authorization will be required to proceed.</p>' : ''}`,
        icon: 'warning',
        showCancelButton: true,
        confirmButtonColor: '#d33',
        confirmButtonText: '<i class="fas fa-trash"></i> Yes, Delete',
        cancelButtonText: '<i class="fas fa-times"></i> Cancel'
    });
    
    if (!confirmDelete.isConfirmed) return;
    
    // If not Super Admin (Admin or Accountant), verify Super Admin password
    if (needsPassword) {
        const passwordVerified = await verifySuperAdminPasswordForPayment();
        if (!passwordVerified) {
            Swal.fire({
                title: '⛔ Access Denied',
                text: 'Super Admin authorization failed. Delete operation cancelled.',
                icon: 'error',
                confirmButtonText: 'OK'
            });
            return;
        }
    }
    
    // Final confirmation with typing
    const finalConfirm = await Swal.fire({
        title: '🔴 FINAL CONFIRMATION',
        html: `<p>${needsPassword ? 'Super Admin authorized. ' : ''}Type <strong style="color: red;">"DELETE"</strong> to permanently delete <strong>${ids.length}</strong> payment records.</p>`,
        input: 'text',
        inputPlaceholder: 'Type DELETE here',
        showCancelButton: true,
        confirmButtonText: 'Permanently Delete',
        cancelButtonText: 'Cancel',
        confirmButtonColor: '#d33',
        preConfirm: (inputValue) => {
            if (inputValue !== 'DELETE') {
                Swal.showValidationMessage('Please type "DELETE" to confirm');
                return false;
            }
            return true;
        }
    });
    
    if (finalConfirm.isConfirmed) {
        Swal.fire({ 
            title: 'Deleting...', 
            text: `Removing ${ids.length} payment records...`,
            allowOutsideClick: false, 
            didOpen: () => Swal.showLoading() 
        });
        
        try {
            for (const id of ids) {
                await deletePayment(id);
            }
            Swal.fire({
                title: '✅ Deleted!',
                text: `${ids.length} payment records have been deleted successfully.`,
                icon: 'success',
                confirmButtonText: 'OK'
            });
            await refreshPayments();
        } catch (error) {
            Swal.fire({
                title: '❌ Error!',
                text: error.message,
                icon: 'error',
                confirmButtonText: 'OK'
            });
        }
    }
};

// ============================================
// EXPORT PAYMENTS
// ============================================

window.exportPayments = async function() {
    await getPayments();
    await getStudentsForPayments();
    
    const exportData = allPaymentsList.map(p => {
        const student = allStudentsList.find(s => s.id === p.student_id);
        return {
            'Receipt No': p.receipt_no,
            'Student Name': student?.name || 'Unknown',
            'Class': student?.class || '-',
            'Fee Type': p.fee_type,
            'Amount (UGX)': p.amount,
            'Payment Method': p.payment_method,
            'Date': p.payment_date,
            'Term': p.term,
            'Year': p.year,
            'Remarks': p.remarks || '-'
        };
    });
    
    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, `${currentLevel}_Payments`);
    XLSX.writeFile(wb, `Payments_${currentLevel}_${new Date().toISOString().split('T')[0]}.xlsx`);
    
    Swal.fire('Exported!', `${exportData.length} payments exported.`, 'success');
};

// ============================================
// QUICK RECORD PAYMENT
// ============================================

window.quickRecordPayment = async function(studentId) {
    await loadFeeStructure();
    await getStudentsForPayments();
    await getPayments();
    
    const student = allStudentsList.find(s => s.id === studentId);
    if (!student) return;
    
    const currentYear = new Date().getFullYear().toString();
    const currentTerm = getCurrentTerm();
    const status = await calculateStudentFeeStatusWithCarryForward(studentId, currentYear, currentTerm);
    
    if (status.status === 'NO_FEE') {
        Swal.fire('Cannot Record Payment', 'No fee structure found. Please add fee in Settings.', 'warning');
        return;
    }
    
    const { value: amount } = await Swal.fire({
        title: `Record Payment for ${escapeHtml(student.name)}`,
        html: `
            <div class="text-start">
                <p><strong>Current Balance:</strong> ${formatMoney(status.balance)}</p>
                <p><strong>Term Fee:</strong> ${formatMoney(status.termFee)}</p>
                <label class="form-label mt-2">Amount (UGX)</label>
                <input type="number" id="quickAmount" class="form-control" min="0" step="1000">
                <label class="form-label mt-2">Payment Method</label>
                <select id="quickMethod" class="form-select">
                    <option value="Cash">Cash</option>
                    <option value="Bank Transfer">Bank Transfer</option>
                    <option value="Mobile Money">Mobile Money</option>
                </select>
            </div>
        `,
        showCancelButton: true,
        confirmButtonText: 'Record Payment',
        preConfirm: () => {
            const amt = parseInt(document.getElementById('quickAmount').value);
            if (!amt || amt <= 0) {
                Swal.showValidationMessage('Enter valid amount');
                return false;
            }
            return { amount: amt, method: document.getElementById('quickMethod').value };
        }
    });
    
    if (amount) {
        Swal.fire({ title: 'Processing...', allowOutsideClick: false, didOpen: () => Swal.showLoading() });
        try {
            await processPaymentWithCarryForward(
                studentId, amount.amount, 'Tuition Fee', amount.method,
                new Date().toISOString().split('T')[0], currentTerm, currentYear, 'Quick payment'
            );
            Swal.fire('Success!', 'Payment recorded.', 'success');
            await refreshPayments();
            showFeeDefaultersModal();
        } catch (error) {
            Swal.fire('Error', error.message, 'error');
        }
    }
};

