// INITIALIZATION
// ============================================

console.log('✅ Reports Module Loaded - Grades from Marks Module');
console.log('✅ Supports both O-Level and A-Level');
console.log('✅ Fee Structure REMOVED from Reports');
console.log('✅ Class Teacher from School Settings');
