// ============================================
// ACADEMIC CALENDAR - COMPLETE MODULE
// ============================================

// ============================================
// GLOBAL VARIABLES
// ============================================

let academicTerms = [];
let academicHolidays = [];
let academicExams = [];
let academicEvents = [];
let isLoading = false;

// ============================================
// HELPER FUNCTIONS
// ============================================

function escapeHtml(text) {
    if (!text) return '';
    const div = document.createElement('div');
    div.textContent = text;
    return div.innerHTML;
}

function formatDate(dateString) {
    if (!dateString) return '-';
    try {
        const date = new Date(dateString);
        return date.toLocaleDateString('en-GB', {
            day: '2-digit',
            month: 'short',
            year: 'numeric'
        });
    } catch (error) {
        return dateString;
    }
}

function getCurrentDate() {
    const date = new Date();
    return date.toISOString().split('T')[0];
}

// ============================================
// UPDATE CURRENT STATUS (Dynamic)
// ============================================

async function updateAcademicStatus() {
    try {
        const today = new Date();
        const currentYear = today.getFullYear().toString();
        
        // Get active term from database
        const { data: terms, error } = await sb
            .from('academic_terms')
            .select('*')
            .order('year', { ascending: false })
            .order('term_name', { ascending: true });
        
        if (error) throw error;
        
        if (!terms || terms.length === 0) {
            document.getElementById('currentYear').innerText = currentYear;
            document.getElementById('currentTerm').innerText = 'Not Set';
            document.getElementById('weeksElapsed').innerText = '0';
            document.getElementById('weeksRemaining').innerText = '0';
            return;
        }
        
        let activeTerm = null;
        let weeksElapsed = 0;
        let weeksRemaining = 0;
        
        for (const term of terms) {
            const startDate = new Date(term.start_date);
            const endDate = new Date(term.end_date);
            
            if (today >= startDate && today <= endDate) {
                activeTerm = term;
                const daysElapsed = Math.floor((today - startDate) / (1000 * 60 * 60 * 24));
                weeksElapsed = Math.floor(daysElapsed / 7);
                if (weeksElapsed < 0) weeksElapsed = 0;
                
                const daysRemaining = Math.floor((endDate - today) / (1000 * 60 * 60 * 24));
                weeksRemaining = Math.floor(daysRemaining / 7);
                if (weeksRemaining < 0) weeksRemaining = 0;
                break;
            }
        }
        
        if (!activeTerm) {
            const upcomingTerms = terms.filter(t => new Date(t.start_date) > today);
            if (upcomingTerms.length > 0) {
                activeTerm = upcomingTerms[0];
                weeksElapsed = 0;
                const startDate = new Date(activeTerm.start_date);
                const daysUntil = Math.floor((startDate - today) / (1000 * 60 * 60 * 24));
                weeksRemaining = Math.floor(daysUntil / 7);
            } else {
                activeTerm = terms[0];
            }
        }
        
        document.getElementById('currentYear').innerText = activeTerm?.year || currentYear;
        document.getElementById('currentTerm').innerText = activeTerm?.term_name || 'No Active Term';
        document.getElementById('weeksElapsed').innerText = weeksElapsed;
        document.getElementById('weeksRemaining').innerText = weeksRemaining;
        
    } catch (error) {
        console.error("❌ Error updating academic status:", error);
    }
}

// ============================================
// LOAD ALL ACADEMIC DATA
// ============================================

async function loadAcademicData() {
    if (isLoading) return;
    
    try {
        isLoading = true;
        console.log("🔄 Loading academic data...");
        
        // Load Terms
        const { data: termsData, error: termsError } = await sb
            .from('academic_terms')
            .select('*')
            .order('year', { ascending: false })
            .order('term_name', { ascending: true });
        
        if (termsError) {
            console.error("❌ Terms error:", termsError);
        } else if (termsData) {
            academicTerms = termsData;
            renderTermsTable();
            console.log(`✅ Loaded ${academicTerms.length} terms`);
        }
        
        // Load Holidays
        const { data: holidaysData, error: holidaysError } = await sb
            .from('academic_holidays')
            .select('*')
            .order('start_date', { ascending: true });
        
        if (holidaysError) {
            console.error("❌ Holidays error:", holidaysError);
        } else if (holidaysData) {
            academicHolidays = holidaysData;
            renderHolidaysTable();
            console.log(`✅ Loaded ${academicHolidays.length} holidays`);
        }
        
        // Load Exams
        const { data: examsData, error: examsError } = await sb
            .from('academic_exams')
            .select('*')
            .order('start_date', { ascending: true });
        
        if (examsError) {
            console.error("❌ Exams error:", examsError);
        } else if (examsData) {
            academicExams = examsData;
            renderExamsTable();
            console.log(`✅ Loaded ${academicExams.length} exams`);
        }
        
        // Load Events
        const { data: eventsData, error: eventsError } = await sb
            .from('academic_events')
            .select('*')
            .order('event_date', { ascending: true });
        
        if (eventsError) {
            console.error("❌ Events error:", eventsError);
        } else if (eventsData) {
            academicEvents = eventsData;
            renderEventsTable();
            console.log(`✅ Loaded ${academicEvents.length} events`);
        }
        
        // Update status display
        await updateAcademicStatus();
        
    } catch (error) {
        console.error('❌ Error loading academic data:', error);
    } finally {
        isLoading = false;
    }
}

// ============================================
// RENDER TERMS TABLE
// ============================================

function renderTermsTable() {
    const tbody = document.getElementById('termsTableBody');
    if (!tbody) {
        console.warn("⚠️ termsTableBody not found");
        return;
    }
    
    if (academicTerms.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="6" class="text-center py-3 text-muted">
                    <i class="fas fa-calendar-plus"></i> No terms configured. Click "Add Term" to get started.
                </td>
            </tr>
        `;
        return;
    }
    
    let html = '';
    const today = new Date();
    
    for (const term of academicTerms) {
        const startDate = new Date(term.start_date);
        const endDate = new Date(term.end_date);
        let status = '';
        
        if (today >= startDate && today <= endDate) {
            status = '<span class="badge bg-success">✅ Active</span>';
        } else if (today < startDate) {
            status = '<span class="badge bg-warning">⏳ Upcoming</span>';
        } else {
            status = '<span class="badge bg-secondary">📅 Completed</span>';
        }
        
        html += `
            <tr>
                <td class="text-center"><strong>${term.year || '-'}</strong></td>
                <td class="text-center"><strong>${escapeHtml(term.term_name)}</strong></td>
                <td class="text-center">${formatDate(term.start_date)}</td>
                <td class="text-center">${formatDate(term.end_date)}</td>
                <td class="text-center">${status}</td>
                <td class="text-center">
                    <button class="btn btn-sm btn-primary me-1" onclick="editTerm('${term.id}')" title="Edit">
                        <i class="fas fa-edit"></i>
                    </button>
                    <button class="btn btn-sm btn-danger" onclick="deleteTerm('${term.id}')" title="Delete">
                        <i class="fas fa-trash"></i>
                    </button>
                </td>
            </tr>
        `;
    }
    tbody.innerHTML = html;
}

